BEGIN;
INSERT INTO attachment(id,path,scope,creator_user_id,referer_time) VALUES (900000001,'v5-synthetic/key','private',101,1);
INSERT INTO attachment(id,path,scope,creator_user_id,referer_time) VALUES (900000002,'v5-synthetic/key','private',101,1) ON CONFLICT(path) DO UPDATE SET referer_time=attachment.referer_time+1;
DO $$ BEGIN IF (SELECT referer_time FROM attachment WHERE id=900000001) <> 2 THEN RAISE EXCEPTION 'counter probe failed'; END IF; END $$;
SELECT 'OBSERVED_CONFIRM_STYLE_UPSERT_COUNT_2' AS evidence;
INSERT INTO attach_pending(object_key,bucket,scope,creator_user_id) VALUES ('v5-synthetic/pending','bucket-a','private',101);
INSERT INTO attach_pending(object_key,bucket,scope,creator_user_id) VALUES ('v5-synthetic/pending','bucket-b','public',202) ON CONFLICT(object_key) DO UPDATE SET bucket=EXCLUDED.bucket,scope=EXCLUDED.scope,creator_user_id=EXCLUDED.creator_user_id,created_at=NOW();
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM attach_pending WHERE object_key='v5-synthetic/pending' AND bucket='bucket-b' AND creator_user_id=202) THEN RAISE EXCEPTION 'pending mutation probe failed'; END IF; END $$;
SELECT 'OBSERVED_PENDING_IDENTITY_MUTABLE' AS evidence;
UPDATE attachment SET path='v5-synthetic/mutated', creator_user_id=202 WHERE id=900000001;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM attachment WHERE id=900000001 AND creator_user_id=202 AND path='v5-synthetic/mutated') THEN RAISE EXCEPTION 'asset mutation probe failed'; END IF; END $$;
SELECT 'OBSERVED_ATTACHMENT_IDENTITY_NO_DB_GUARD' AS evidence;
ROLLBACK;
SELECT count(*) AS remaining_synthetic_rows FROM attachment WHERE id IN (900000001,900000002);
